{"code":"def transform(grid):
    a=[r[:] for r in grid]
    h,w=len(a),len(a[0])
    # The several 5s on an edge are a stencil; a perpendicular edge
    # gives the rows/columns on which to print it in purple (2).
    br=[]
    for j in range(w):
        if sum(a[i][j]==5 for i in range(h))>=2 and j in (0,w-1): br.append(j)
    tr=[]
    for i in range(h):
        if sum(a[i][j]==5 for j in range(w))>=2 and i in (0,h-1): tr.append(i)
    if tr and br:
        # horizontal edge is stencil, vertical edge is index, unless
        # the horizontal edges are merely the two ends of a vertical stencil
        p=tr[0]; jset=[j for j in range(w) if a[p][j]==5]
        for j in br:
            iset=[i for i in range(h) if a[i][j]==5]
            for i in iset:
                for x in jset:
                    if a[i][x]==0: a[i][x]=2
    return a"}

